  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Blue sky
  brush.beginShape();
  brush.vertex(0, 0);       // Top left
  brush.vertex(400, 0);     // Top right
  brush.vertex(200, 400);   // Bottom center
  brush.endShape(true);

  // Green hills
  brush.fill("#98FB98", 255); // Light green hills
  brush.beginShape();
  brush.vertex(0, 200);       // Hill top left
  brush.vertex(400, 200);     // Hill top right
  brush.vertex(200, 300);     // Hill center
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Golden sun
  brush.beginShape();
  brush.vertex(100, 100);     // Sun top left
  brush.vertex(300, 100);     // Sun top right
  brush.vertex(200, 50);      // Sun center
  brush.endShape(true);
}

